/**
 * The frontend's copies of the server's vocabularies, asserted against the server.
 *
 * ADR-0003 makes the server authoritative for both of these. The frontend needs them locally — a
 * form cannot wait for a round trip to know its own fields — so they are duplicated, and this is
 * what keeps the duplication honest rather than hopeful.
 *
 * `server-facts.json` is generated by `kratos-server/cmd/resumefacts` (run it to regenerate; the
 * command documents what each section is for). Two kinds of drift are covered, and they fail
 * differently:
 *
 *   - **The lists.** `METADATA_KEYS` and `METADATA_MAX_LENGTH` must equal the server's field list
 *     and rune limits. This drift has already happened: `summary` was missing from one of the
 *     frontend's two copies of the field list, and nothing anywhere compared either copy with the
 *     server.
 *   - **The literals.** Grant names are bare strings at their call sites (`resourceType: 'ai'`,
 *     `permission: 'use_global'`), which no type can check, so they are read out of the source
 *     text and matched against the server's vocabulary. Renaming a Go constant would otherwise
 *     break those screens at runtime, silently.
 */

import { describe, expect, it } from 'vitest';
import { readFileSync, readdirSync } from 'node:fs';
import { join, relative } from 'node:path';
import serverFacts from '@/lib/__fixtures__/server-facts.json';
import { APPROVAL_FILTERS } from '@/lib/ai-providers';
import { METADATA_KEYS, METADATA_MAX_LENGTH } from '@/lib/resume-metadata';

const facts = serverFacts;

/** Repository root: this file lives in `src/lib/`, two levels down. */
const ROOT = new URL('../../', import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, '$1');

/** Every application `.ts`/`.tsx` under `src/`. Tests are excluded: they assert, they do not send. */
function applicationSources(): string[] {
  const out: string[] = [];
  const walk = (dir: string): void => {
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
      const full = join(dir, entry.name);
      if (entry.isDirectory()) {
        walk(full);
      } else if (/\.tsx?$/.test(entry.name) && !/\.test\.tsx?$/.test(entry.name)) {
        out.push(full);
      }
    }
  };
  walk(join(ROOT, 'src'));
  return out;
}

/** A grant name written as a literal, with the file it is written in. */
interface GrantLiteral {
  file: string;
  field: string;
  value: string;
}

function grantLiterals(): GrantLiteral[] {
  const fields = ['resourceType', 'permission', 'approval_status'] as const;
  const pattern = new RegExp(`\\b(${fields.join('|')})\\s*:\\s*'([^']*)'`, 'g');
  const found: GrantLiteral[] = [];
  for (const file of applicationSources()) {
    for (const match of readFileSync(file, 'utf8').matchAll(pattern)) {
      found.push({ file: relative(ROOT, file), field: match[1], value: match[2] });
    }
  }
  return found;
}

describe('the metadata vocabulary matches the server', () => {
  it('names exactly the server’s fields, in the server’s order', () => {
    // Order is part of the contract: it is the form layout, and it is why the server reports the
    // first invalid field as the topmost one on screen.
    expect([...METADATA_KEYS]).toEqual(facts.metadata_fields);
  });

  it('mirrors every limit the server enforces, and invents none', () => {
    // The frontend check is convenience — the server still validates — but a limit that is
    // *higher* here means a save the server will reject, and one that is lower refuses input the
    // server would have accepted.
    expect(METADATA_MAX_LENGTH).toEqual(facts.metadata_limits);
  });
});

describe('the approval grant names match the server', () => {
  it('offers only resource types the server knows', () => {
    for (const filter of APPROVAL_FILTERS) {
      expect(facts.grant.resource_types, `filter "${filter.key}"`).toContain(filter.resourceType);
    }
  });

  it('writes no grant name the server has not declared', () => {
    const literals = grantLiterals();
    // Guards the test itself: if the property names were ever renamed, this whole check would
    // silently become a loop over nothing.
    expect(literals.length).toBeGreaterThan(2);

    const vocabulary: Record<string, string[]> = {
      resourceType: facts.grant.resource_types,
      permission: facts.grant.permissions,
      approval_status: facts.grant.statuses,
    };

    for (const { file, field, value } of literals) {
      expect(vocabulary[field], `${file} sets ${field} to '${value}'`).toContain(value);
    }
  });
});
